// Version A: defer optional feature until used
class FeatureRegistryA {
  getFeature(name: string) {
    if (!this.loaded[name]) {
      this.loaded[name] = loadFeatureDynamically(name)
    }
    return this.loaded[name]
  }
}

// Version B: implement all optional features in core up front
class FeatureRegistryB {
  constructor() { this.features = { a: featureA(), b: featureB(), c: featureC() } }
  getFeature(name: string) { return this.features[name] }
}
